mapper.select:
select channel.channel_code, channel.config_json ->> 'secret_ref' as secret_ref, secret.id as secret_version_id, secret.version_no from batch.file_channel_config channel left join batch.secret_version secret on secret.tenant_id = channel.tenant_id and secret.secret_ref = channel.config_json ->> 'secret_ref' and secret.current_version = true and secret.secret_status = 'PUBLISHED' and secret.revoked_at is null and (secret.effective_from_at is null or secret.effective_from_at <= current_timestamp) and (secret.effective_to_at is null or secret.effective_to_at > current_timestamp) where channel.tenant_id = #{tenantId} and channel.is_deleted = false and channel.channel_code in
#{channel}
and nullif(btrim(channel.config_json ->> 'secret_ref'), '') is not null
